p='src/prompt_mode.rs'
s=open(p).read()
def rep(old,new):
    global s
    assert s.count(old)==1,old; s=s.replace(old,new)
rep("""        let pull = (STRETCH_GIVE * (1. - (-held / STRETCH_GIVE).exp())).min(STRETCH_PULL);""",
"""        let pull = (STRETCH_GIVE * held / (STRETCH_GIVE + held)).min(STRETCH_PULL);""")
old_start=s.index("/// How quickly the stretch stiffens")
old_end=s.index("const STRETCH_GIVE: f32 = 64.5;")+len("const STRETCH_GIVE: f32 = 64.5;")
s=s[:old_start]+"""/// How quickly the stretch stiffens, as a rubber band does: it gives all of
/// a scroll at first, less and less the further it goes, and still gives a
/// little right up to the barrier, reaching [`STRETCH_PULL`] just as the
/// build-up reaches [`SCROLL_BARRIER`].
const STRETCH_GIVE: f32 = STRETCH_PULL * SCROLL_BARRIER / (SCROLL_BARRIER - STRETCH_PULL);"""+s[old_end:]
rep("const SCROLL_BARRIER: f32 = 320.;","const SCROLL_BARRIER: f32 = 512.;")
# tests
rep("""        wheel(cx, 0., -60.);
        wheel(cx, 0., 200.);
        assert!(!expanded(cx), "scrolling back didn't take it down");""","""        wheel(cx, 0., -60.);
        wheel(cx, 0., 400.);
        assert!(!expanded(cx), "scrolling back didn't take it down");""")
rep("""        wheel(cx, 0., -120.);
        wheel(cx, 0., -120.);
        assert!(expanded(cx), "it crossed back short of the barrier");
        wheel(cx, 0., -120.);""","""        for _ in 0..4 {
            wheel(cx, 0., -120.);
        }
        assert!(expanded(cx), "it crossed back short of the barrier");
        wheel(cx, 0., -120.);""")
rep("""            for _ in 0..6 {""","""            for _ in 0..9 {""")
rep("""        wheel(cx, 120.);
        assert!(!expanded(cx), "it crossed over before the barrier");
        wheel(cx, 60.);
        assert!(expanded(cx), "what went past the top didn't build up");""","""        wheel(cx, 300.);
        assert!(!expanded(cx), "it crossed over before the barrier");
        wheel(cx, 80.);
        assert!(expanded(cx), "what went past the top didn't build up");""")
rep("""        assert!(pull(10.) > 9., "it resists from the start");""","""        assert!(pull(5.) > 4.5, "it resists from the start");
        // Still giving, however far it has gone, up to the barrier.
        assert!(pull(SCROLL_BARRIER * 0.5) + 1. < pull(SCROLL_BARRIER * 0.75));""")
open(p,'w').write(s)
EOF
